// A web browser for a frame, the way Lynx and Opera Mini browsed: a page is
// its words, links, pictures and forms, set in one column in the frame's own
// type. No style sheets are downloaded and no scripts run, so a page shows in
// a few seconds on an ESP32 (most of them its TLS handshake) and a news site
// of megabytes costs what its words do.
//
// - The frame's runtime reads the page as its bytes come off the socket (fetch's
//   onChunk and `digest: "html"`, docs/html-digest.md): scripts, style and
//   inline SVG are skipped as they pass and never reach JavaScript, and what
//   does is a record a block. page.ts makes the page of them, a flat list of
//   blocks, and folds its navigation, sidebars and footer into one line each.
// - lay.ts breaks the blocks into lines for the page's width, as far down as
//   is looked at.
// - This file draws the lines around where the page is scrolled to (a page of
//   ten thousand lines costs a screenful), and is the browser around them: the
//   address and search, back and forward (pages seen stay in memory, so Back
//   is at once), bookmarks and history on a start page, text size, pictures on
//   or off, forms (GET and POST), feeds, plain text, Markdown and JSON.
//
// The page shows while it downloads where the frame draws fast (an LCD), and
// in one refresh when it is in on e-paper.

import { BOLD, CODE, DIM, FIELD, FOLD, GAP, H, HR, IMG, ITALIC, LI, LINK, P, PRE, SHIFT, STRUCK, add, blank, feed as feedOf_, feedPush,
  finish, idAt, jsonDoc, plain, plainPush, resolve, runsOf, sniff, take, type Doc } from './page'
import { PAD, cut, drawn, heightOf, indentOf, lineOf, pictureBox, reach, rowAt, rowOf, rows, scaleOf, type Look, type Rows } from './lay'
const SEARCH = 'https://lite.duckduckgo.com/lite/?q='
const ARCHIVE = 'https://web.archive.org/web/2id_/'
const MAX_HISTORY = 50
const HEADERS: Record<string, string> = {
  // A text browser by name: sites that turn a browser they do not know away answer Lynx with plain HTML.
  'User-Agent': 'Lynx/2.9.2 libwww-FM/2.14 FrameOS',
  Accept: 'text/html,application/xhtml+xml,text/plain;q=0.9,*/*;q=0.5',
  'Accept-Language': 'en',
}
const ZOOMS = [0.7, 0.8, 0.9, 1, 1.15, 1.3, 1.5, 1.75, 2.1]
const MARKS = [
  ['Hacker News', 'https://news.ycombinator.com/'],
  ['Wikipedia', 'https://en.wikipedia.org/wiki/Special:Random'],
  ['NPR, text only', 'https://text.npr.org/'],
  ['CNN lite', 'https://lite.cnn.com/'],
  ['BBC News', 'https://www.bbc.com/news'],
  ['The Guardian', 'https://www.theguardian.com/international'],
  ['Lobsters', 'https://lobste.rs/'],
  ['Weather', 'https://wttr.in/?format=4'],
  ['FrameOS', 'https://frameos.net/'],
]

type Entry = { u: string; b?: number; o?: number; post?: string } // b, o: the block and letter at the top of the screen
type Nav = { list: Entry[]; at: number }
type Page = {
  id: string // its address, and what was posted to it
  url: string // what was asked for (no #part)
  doc: Doc
  rows: Rows | null
  key: string // what `rows` were set for
  loading: boolean
  status: number
  bytes: number
  picture: string // the page is this picture
  other: string // or something this cannot show: what
  note: string // a line above the page (it wants scripts, it was cut)
  at: number // when it was opened
}
type Load = { url: string; seq: number; page: Page; plain: any; feed: any; json: string[] | null; kind: string; head: string;
  type: string; shown: boolean; t0: number; first: number; stop: boolean; spent: number }

let seq = 0
let page: Page | null = null // the page showing
let stage: Page | null = null // the page coming, until there is enough of it to show
let load: Load | null = null
let wantId = '' // the #part of the page to go to once it is read
let inGet = false
let embeddedNow = false
let failure: { url: string; why: string; status: number } | null = null
let typed: string | null = null // the address while it is typed
let held = '' // the link whose card is up
let menu = false
let hops = 0
let scrollY = 0
let scrollAttr = 0
let rev = 0 // goes up when what is drawn changed
let built = [0, 0] // the rows drawn span this much of the page
let viewH = 400
let pending: Entry | null = null // where to scroll once the page's rows reach it
const pages = new Map<string, Page>() // pages seen, newest last
const appRef: { app: any } = { app: null }

const kept = (key: string, empty: any) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}
const log = (...parts: any[]) => frameos.log('browser: ' + parts.join(' '))

// --- where it has been ---

const homeOf = (app: any) => normalize(String(app.state.homepage || app.config.homepage || '')) || 'about:home'

function readNav(app: any): Nav {
  const nav = kept('nav', null)
  if (nav && Array.isArray(nav.list) && nav.list.length) return nav
  return { list: [{ u: homeOf(app) }], at: 0 }
}
const saveNav = (nav: Nav) => frameos.remember('nav', nav)

// What was typed as an address: one, or words to search for.
export function normalize(text: string): string {
  const t = text.trim()
  if (!t) return ''
  if (/^(https?:\/\/|about:)/i.test(t)) return t
  if (/^[\w-]+(\.[\w-]+)+(:\d+)?(\/\S*)?$/.test(t) || /^localhost(:\d+)?(\/|$)/.test(t))
    return 'http' + (/^(localhost|\d+\.\d+\.\d+\.\d+)/.test(t) ? '' : 's') + '://' + t
  return SEARCH + encodeURIComponent(t).replace(/%20/g, '+')
}

// A search result's link is the search's own redirect: the page it names instead.
function unwrap(url: string): string {
  const m = /^https?:\/\/(?:html\.|lite\.|www\.)?duckduckgo\.com\/l\/\?(?:.*&)?uddg=([^&]+)/.exec(url)
  if (m) {
    try {
      return decodeURIComponent(m[1])
    } catch (e) {
      return url
    }
  }
  return url
}

// Where the screen is in the page, as a block and a letter: the same place at another text size or width.
function mark(entry: Entry) {
  const r = page && page.rows
  if (!r || !r.n) return
  const row = Math.min(r.n - 1, rowAt(r, scrollY + 1))
  entry.b = r.block[row]
  entry.o = r.from[row]
}

function open(url: string, post?: string) {
  const app = appRef.app
  const nav = readNav(app)
  mark(nav.list[nav.at])
  nav.list = nav.list.slice(0, nav.at + 1)
  const u = unwrap(url)
  const hash = u.indexOf('#')
  const here = page && hash > 0 && u.slice(0, hash) === page.url && !post && !stage
  nav.list.push(post !== undefined ? { u, post } : { u })
  if (nav.list.length > MAX_HISTORY) nav.list = nav.list.slice(-MAX_HISTORY)
  nav.at = nav.list.length - 1
  saveNav(nav)
  typed = null
  held = ''
  menu = false
  failure = null
  hops = 0
  if (here) jumpToId(u.slice(hash + 1))
  else remember(u)
}

const bare = (url: string) => {
  const hash = url.indexOf('#')
  return hash < 0 ? url : url.slice(0, hash)
}
const idOf = (entry: Entry) => bare(entry.u) + (entry.post !== undefined ? ' \u2190 ' + entry.post : '')

// A place visited, for the start page: the newest thirty, by address.
function remember(url: string) {
  if (!/^https?:/.test(url)) return
  const seen: string[] = kept('seen', [])
  const at = seen.indexOf(url)
  if (at >= 0) seen.splice(at, 1)
  seen.unshift(url)
  frameos.remember('seen', seen.slice(0, 30))
}

function step(by: number): boolean {
  const nav = readNav(appRef.app)
  const at = nav.at + by
  if (at < 0 || at >= nav.list.length) return false
  mark(nav.list[nav.at])
  nav.at = at
  saveNav(nav)
  typed = null
  held = ''
  menu = false
  failure = null
  return true
}

function reload() {
  const nav = readNav(appRef.app)
  pages.delete(idOf(nav.list[nav.at]))
  mark(nav.list[nav.at])
  saveNav(nav)
  if (load) load.stop = true
  load = null
  stage = null
  failure = null
  if (page && page.id === idOf(nav.list[nav.at])) page = Object.assign({}, page, { id: '' }) // stays up until it is in again
}

function jumpTo(y: number) {
  // scrollTop moves the box only when it changes (docs/jsx-ui.md): the same place again is told a hair apart.
  y = Math.max(0, Math.round(y))
  scrollAttr = scrollAttr === y ? y + 0.01 : y
  scrollY = y
}

function jumpToId(id: string) {
  if (!page) return
  let name = id
  try {
    name = decodeURIComponent(id)
  } catch (e) {
    // as it is
  }
  const block = idAt(page.doc, name)
  if (block < 0) return jumpTo(0)
  pending = { u: page.url, b: block, o: 0 }
  // Folded away: its folds open.
  for (const f of page.doc.folds)
    if (!f.open && f.end > f.at && block > f.at && block < f.end) {
      f.open = true
      if (page.rows) cut(page.rows, f.at)
    }
  rev++
}

// --- bookmarks, kept on the frame's disk ---

function marks(app: any): string[][] {
  let list: any = app.state.marks
  if (typeof list === 'string') {
    try {
      list = JSON.parse(list)
    } catch (e) {
      list = null
    }
  }
  return Array.isArray(list) && list.length ? list : MARKS
}

function toggleMark(app: any) {
  if (!page || !/^https?:/.test(page.url)) return
  const list = marks(app).slice()
  const at = list.findIndex((m) => m[1] === page!.url)
  if (at >= 0) list.splice(at, 1)
  else list.unshift([page.doc.title || page.url.replace(/^https?:\/\//, ''), page.url])
  frameos.setState('marks', list)
  pages.delete('about:home')
}

// --- the browser's own pages ---

const hostOf = (url: string) => (/^https?:\/\/([^/?#]+)/i.exec(url) || ['', url])[1].replace(/^www\./, '')

function about(app: any, url: string): Doc {
  const d = blank(url)
  const name = url.replace(/^about:/, '').replace(/[?#].*$/, '')
  const list = (title: string, items: string[][]) => {
    if (!items.length) return
    add(d, H, title, null, GAP + (3 << SHIFT))
    for (const [label, to, note] of items) {
      d.links.push(to)
      const runs = [0, (d.links.length - 1) * LINK]
      if (note) runs.push(label.length, DIM)
      d.mark[add(d, LI, label + (note ? '  ' + note : ''), runs, 1)] = '\u2022'
    }
  }
  const short = (u: string) => u.replace(/^https?:\/\//, '').slice(0, 90)
  const seen: string[] = kept('seen', [])
  if (name === 'history') {
    d.title = 'History'
    add(d, H, 'History', null, 1 << SHIFT)
    list('This window', readNav(app).list.map((e) => e.u).reverse().filter((u) => !u.startsWith('about:')).slice(0, 30).map((u) => [short(u), u]))
    list('Lately', seen.map((u) => [short(u), u]))
    return d
  }
  d.title = 'Start'
  d.forms.push({ action: 'about:go', post: false, fields: [0, 1] })
  d.fields.push({ form: 0, type: 'text', name: 'q', value: '', label: 'Search the web, or type an address' },
    { form: 0, type: 'submit', name: '', value: '', label: 'Go' })
  add(d, FIELD, '', null, GAP)
  add(d, FIELD, '', null, 1 << SHIFT)
  list('Bookmarks', marks(app).map((m) => [m[0], m[1], hostOf(m[1])]))
  list('Lately', seen.slice(0, 8).map((u) => [short(u), u]))
  if (seen.length > 8) {
    d.links.push('about:history')
    add(d, P, 'All history', [0, (d.links.length - 1) * LINK], GAP)
  }
  add(d, P, 'Hold a link for its QR code. The menu has text size, pictures, bookmarks and a page\u2019s archived copy.', [0, DIM], GAP)
  return d
}

// --- downloading ---

function newPage(id: string, url: string, max: number): Page {
  return { id, url, doc: blank(url, max), rows: null, key: '', loading: true, status: 0, bytes: 0, picture: '', other: '', note: '', at: Date.now() }
}

function keep(p: Page, embedded: boolean) {
  pages.delete(p.id)
  pages.set(p.id, p)
  // An ESP32 keeps what a few pages' words take; a Pi the last dozen pages.
  let chars = 0
  for (const q of pages.values()) chars += q.doc.chars + q.doc.n * 40
  while (pages.size > (embedded ? 4 : 12) || (embedded && pages.size > 1 && chars > 300000)) {
    const oldest = pages.keys().next().value as string
    const q = pages.get(oldest) as Page
    chars -= q.doc.chars + q.doc.n * 40
    pages.delete(oldest)
  }
}

// The next piece of the page being downloaded: the runtime's records of it (`digested`), or its text
// as it came. False: no more is wanted.
function feed(L: Load, text: string, last: boolean, digested: boolean): boolean {
  if (L.stop || L.seq !== seq) return false
  const p = L.page
  const d = p.doc
  p.bytes += text.length
  const t = Date.now()
  let more = true
  if (digested) {
    L.kind = 'html'
    more = take(d, text)
    L.spent += Date.now() - t
    return more
  }
  if (!L.kind) {
    // What it is, from its first bytes.
    L.head += text
    if (L.head.length < 512 && !last) return true
    text = L.head
    L.head = ''
    L.kind = sniff(text, L.type, d.url)
    if (L.kind === 'image') {
      p.picture = d.url
      return false
    }
    if (L.kind === 'pdf' || L.kind === 'binary') {
      p.other = L.kind === 'pdf' ? 'a PDF' : 'a file, not a page'
      return false
    }
    if (L.kind === 'json') L.json = []
    else if (L.kind === 'text' || L.kind === 'markdown') L.plain = plain(d, L.kind === 'markdown')
    else if (L.kind === 'feed') L.feed = feedOf_(d)
    else L.plain = plain(d, false) // markup the runtime did not take for a page: as it is written
  }
  if (L.json) {
    L.json.push(text)
    if (L.json.length > 40) more = false
    if (last || !more) jsonDoc(d, L.json.join(''))
  } else if (L.plain) more = plainPush(L.plain, text, last)
  else if (L.feed) more = feedPush(L.feed, text, last)
  L.spent += Date.now() - t
  return more
}

// The download is over: the page as it stands is the page.
function settle(L: Load, why: string) {
  if (L.seq !== seq) return
  const p = L.page
  const d = p.doc
  if (L.kind && !p.picture && !p.other) finish(d)
  p.loading = false
  L.plain = L.feed = L.json = null
  if (load === L) load = null
  if (why && !d.chars && !d.imgs.length && !p.picture && !p.other) {
    failure = { url: p.id, why, status: p.status }
    if (stage === p) stage = null
    return
  }
  if (why && why !== 'Stopped') p.note = 'The page stopped coming: ' + why
  if (!p.id.startsWith('about:')) keep(p, embeddedNow)
  let words = 0
  for (let i = 0; i < d.n && words < 400; i++) words += d.text[i].length
  if (!p.picture && !p.other && words < 400 && /^https?:/.test(p.url)) {
    const said = d.text.join(' ')
    if (p.status === 403 || p.status === 429 || p.status === 503 || /javascript|enable js|not a robot|captcha|just a moment|unsupported browser/i.test(said))
      p.note = 'This site asks for a script-running browser, which a frame is not.'
    else if (p.status >= 400) p.note = `The site answered ${p.status}.`
  }
  if (d.cut) p.note = 'This page is longer than the frame keeps: its start is shown.'
  if (wantId && stage === p) {
    const id = wantId
    wantId = ''
    const was = page
    page = p
    jumpToId(id)
    page = was
  }
  if (L.kind !== 'about') log(`${hostOf(p.url)} ${p.status} ${Math.round(p.bytes / 1024)} KB in, ${d.n} blocks, ${Math.round(d.chars / 1024)} KB of text, ${Date.now() - L.t0} ms (first byte ${L.first}, reading ${L.spent})`)
  rev++
}

function begin(app: any, entry: Entry, embedded: boolean, fast: boolean) {
  const url = entry.u
  if (load) load.stop = true
  const p = newPage(idOf(entry), bare(url), embedded ? 360000 : 4000000)
  const L: Load = { url, seq: ++seq, page: p, plain: null, feed: null, json: null, kind: '', head: '', type: '', shown: false,
    t0: Date.now(), first: 0, stop: false, spent: 0 }
  load = L
  stage = p
  failure = null
  pending = entry.b !== undefined ? entry : null
  wantId = entry.b === undefined && url.indexOf('#') > 0 ? url.slice(url.indexOf('#') + 1) : ''
  const hash = url.indexOf('#')
  if (url.startsWith('about:')) {
    p.doc = about(app, url)
    p.status = 200
    L.kind = 'about'
    settle(L, '')
    return
  }
  const init: Record<string, any> = { headers: { ...HEADERS }, timeoutMs: 20000 }
  if (entry.post !== undefined) {
    init.method = 'POST'
    init.body = entry.post
    init.headers['Content-Type'] = 'application/x-www-form-urlencoded'
  }
  const target = hash > 0 ? url.slice(0, hash) : url
  const show = () => {
    // The page's first screenful, then its end: a render each, asked for where this is not one already
    // (a frame that pumps promises). Where a change is a refresh, only the page whole.
    if (!inGet && (fast || !p.loading || failure)) frameos.dispatch('render')
  }
  const head = (status: number, final: string, type: string) => {
    p.status = status
    L.type = type || ''
    if (final && /^https?:/.test(final) && final !== target) {
      // Sent on to another address: that is where its links are read from.
      p.doc.url = p.doc.base = final
    }
  }
  if (!(fetch as any).chunks) {
    // A runtime from before a response came in pieces and pages were read by it (2026.11.15).
    failure = { url: p.id, why: 'This frame\u2019s FrameOS is older than this browser needs. Update it, and the web is here.', status: 0 }
    stage = null
    load = null
    return
  }
  // The body a piece at a time, off the socket, never held whole; HTML read by the runtime on the way.
  {
    let first = true
    const done = fetch(target, { ...init, chunkBytes: 16384, digest: 'html', onChunk: (text: string, info: any) => {
      if (first) {
        first = false
        L.first = Date.now() - L.t0
        head(info.status, info.url, (info.headers && info.headers['content-type']) || '')
      }
      const more = feed(L, text, !!info.done, info.digest === 'html')
      if (info.done || !more) settle(L, info.error || '')
      // Drawn once there is a screenful past what is folded at its top, and again when it is all in.
      if (info.done || !more || (!L.shown && (p.doc.chars > 2500 || p.bytes > 120000))) {
        L.shown = true
        show()
      }
      return more
    } } as any)
    done.then(() => 0, (e: any) => {
      settle(L, String((e && e.message) || e).replace(/^fetch failed: /, ''))
      show()
    })
  }
}

// --- drawing ---

type Theme = { ink: boolean; fast: boolean; px: number; z: number; width: number; look: Look }
let theme: Theme = { ink: false, fast: true, px: 16, z: 1, width: 480, look: { width: 480, px: 16, pics: true, tall: 300, jpegs: false } }

// A text row's pieces: [text, style] for each run it crosses.
function pieces(d: Doc, block: number, from: number, to: number): any[] {
  const text = d.text[block]
  // A line's last space (where it broke) is not drawn.
  while (to > from && text.charCodeAt(to - 1) === 32) to--
  const runs = runsOf(d, block)
  if (!runs) return [text.slice(from, to), 0]
  const out: any[] = []
  for (let j = 0; j < runs.length; j += 2) {
    const a = runs[j]
    const b = j + 2 < runs.length ? runs[j + 2] : text.length
    if (b <= from) continue
    if (a >= to) break
    const s = text.slice(a < from ? from : a, b > to ? to : b)
    if (s) out.push(s, runs[j + 1])
  }
  return out
}

function go(link: number) {
  if (!page) return
  const url = resolve(page.doc.links[link] || '', page.doc.base)
  if (!url) return
  if (/^(mailto|tel):/.test(url)) held = url
  else open(url)
}

function hold(link: number) {
  if (!page) return
  held = resolve(page.doc.links[link] || '', page.doc.base)
}

function toggle(block: number) {
  if (!page || !page.rows) return
  const d = page.doc
  const f = d.folds[d.meta[block] >> SHIFT]
  if (!f) return
  f.open = !f.open
  cut(page.rows, block)
  rev++
}

function submit(form: number, by: number) {
  if (!page) return
  const d = page.doc
  const f = d.forms[form]
  if (!f) return
  const parts: string[] = []
  for (const i of f.fields) {
    const field = d.fields[i]
    if (!field.name) continue
    if (field.type === 'submit' && i !== by) continue
    if ((field.type === 'checkbox' || field.type === 'radio') && !field.on) continue
    parts.push(encodeURIComponent(field.name).replace(/%20/g, '+') + '=' + encodeURIComponent(field.value).replace(/%20/g, '+'))
  }
  const query = parts.join('&')
  if (f.action === 'about:go') {
    const q = d.fields[f.fields[0]].value
    const url = normalize(q)
    if (url) open(url)
    return
  }
  const action = resolve(f.action || d.url, d.base) || d.url
  if (f.post) open(action.replace(/#.*$/, ''), query)
  else open(action.replace(/[?#].*$/, '') + (query ? '?' + query : ''))
}

// Rows drawn as one piece, kept while they do not change. Few: every letter drawn is a node the frame keeps
// (a screenful of text is a thousand), so what is drawn is what shows and a little around it.
const CHUNK = 6
// Pieces to a group. A piece is always the same child of the same group, drawn or not (an empty element
// stands for one that is not), so an element keeps its place in the tree as the page scrolls: the keys'
// ring (Tab, a frame's buttons) stays on the link it is on, and walks the links in the page's order.
const GROUP = 16

// Rows `c * CHUNK` on, as elements at their places.
const Chunk = memo((props: any) => {
  const p = page
  if (!p || !p.rows) return <div />
  const r = p.rows
  const d = p.doc
  const t = theme
  const first = props.c * CHUNK
  const last = Math.min(r.n, first + CHUNK)
  if (first >= last) return <div />
  const top = r.y[first]
  const pad = Math.round(t.px * PAD)
  const linkCls = t.ink ? 'border-b border-[#000000]' : 'text-[#0b57d0] active:bg-[#d2e3fc]'
  const dim = t.ink ? '' : 'text-[#5f6368]'
  const out: any[] = []
  for (let i = first; i < last; i++) {
    const b = r.block[i]
    const kind = d.kind[b]
    const meta = d.meta[b]
    const y = r.y[i] - top
    const h = r.h[i]
    const quote = (meta >> 4) & 7
    let x = pad + indentOf(meta, t.px)
    const room = Math.max(60, t.width - pad - x)
    if (kind === FOLD) {
      const f = d.folds[meta >> SHIFT]
      out.push(
        <div className={`absolute left-[${x}px] top-[${y}px] w-[${room}px] h-[${h}px] flex items-center gap-[${Math.round(t.px * 0.4)}px] px-[${Math.round(t.px * 0.5)}px] rounded-[${Math.round(t.px * 0.3)}px] text-[${Math.round(t.px * 0.92)}px] whitespace-nowrap overflow-hidden ${t.ink ? 'border border-[#000000]' : 'bg-[#f1f3f4] text-[#3c4043] active:bg-[#d4d6d9]'}`}
          onClick={() => toggle(b)}>
          <span className="font-bold">{f.open ? '−' : '+'}</span>
          <span>{f.label}</span>
          <span className={dim}>{f.links > 0 ? `${f.links} links` : ''}</span>
        </div>
      )
      continue
    }
    if (kind === HR) {
      out.push(<div className={`absolute left-[${x}px] top-[${y + (h >> 1)}px] w-[${room}px] h-[1px] ${t.ink ? 'bg-[#000000]' : 'bg-[#c4c7c5]'}`} />)
      continue
    }
    if (kind === IMG) {
      const g = d.imgs[meta >> SHIFT]
      const act = g.link ? () => go(g.link) : () => open(resolve(g.src, d.base))
      if (!drawn(g.src, t.look)) {
        out.push(
          <div className={`absolute left-[${x}px] top-[${y}px] max-w-[${room}px] h-[${h}px] text-[${t.px}px] leading-[${h}px] whitespace-nowrap overflow-hidden italic ${g.link ? linkCls : dim}`}
            onClick={act}>
            {'[' + (g.alt || 'Picture') + ']'}
          </div>
        )
        continue
      }
      const [bw, bh] = pictureBox(g.w, g.h, room, t.look.tall)
      const src = resolve(g.src, d.base) || (g.src.startsWith('data:') ? g.src : '')
      if (src)
        out.push(
          <img src={src} className={`absolute left-[${x}px] top-[${y}px] w-[${bw}px] h-[${bh}px] object-contain ${t.ink ? '' : 'bg-[#f1f3f4]'}`}
            onClick={act} onLongPress={() => (held = g.link ? resolve(d.links[g.link], d.base) : src)} />
        )
      continue
    }
    if (kind === FIELD) {
      const f = d.fields[meta >> SHIFT]
      const fi = meta >> SHIFT
      const box = t.ink ? 'border border-[#000000] bg-[#ffffff] text-[#000000]' : 'border border-[#c4c7c5] bg-[#ffffff] text-[#1f1f1f] focus:border-[#0b57d0]'
      const fh = h - Math.round(t.px * 0.3)
      if (f.type === 'submit') {
        out.push(
          <div look="primary" className={`absolute left-[${x}px] top-[${y}px] h-[${fh}px] flex items-center px-[${Math.round(t.px * 1.1)}px] rounded-[${Math.round(t.px * 0.3)}px] text-[${t.px}px] font-bold whitespace-nowrap ${t.ink ? 'bg-[#000000] text-[#ffffff]' : 'bg-[#0b57d0] text-[#ffffff] active:bg-[#0842a0]'}`}
            onClick={() => submit(f.form, fi)}>
            {f.label || 'Submit'}
          </div>
        )
      } else if (f.type === 'checkbox' || f.type === 'radio') {
        out.push(
          <div className={`absolute left-[${x}px] top-[${y}px] h-[${h}px] flex items-center gap-[${Math.round(t.px * 0.4)}px] text-[${t.px}px] whitespace-nowrap`}
            onClick={() => {
              if (f.type === 'radio') for (const j of d.forms[f.form].fields) if (d.fields[j].type === 'radio' && d.fields[j].name === f.name) d.fields[j].on = false
              f.on = f.type === 'radio' ? true : !f.on
              rev++
            }}>
            <div className={`w-[${Math.round(t.px * 0.9)}px] h-[${Math.round(t.px * 0.9)}px] ${f.type === 'radio' ? 'rounded-full' : ''} border-2 ${t.ink ? 'border-[#000000]' : 'border-[#5f6368]'} ${f.on ? (t.ink ? 'bg-[#000000]' : 'bg-[#0b57d0]') : ''}`} />
            <span>{f.label}</span>
          </div>
        )
      } else if (f.type === 'select') {
        const o = f.options || []
        const items: any[] = []
        for (let k = 0; k < o.length && k < 400; k += 2) items.push(<option value={o[k]}>{o[k + 1]}</option>)
        out.push(
          <select look="field" className={`absolute left-[${x}px] top-[${y}px] w-[${Math.min(room, Math.round(t.px * 22))}px] h-[${fh}px] px-[${Math.round(t.px * 0.5)}px] rounded-[${Math.round(t.px * 0.3)}px] text-[${t.px}px] ${box}`}
            value={f.value} onChange={(e: any) => {
              f.value = String(e.target.value)
              rev++
            }}>
            {items}
          </select>
        )
      } else {
        out.push(
          <input look="field" type={f.type === 'password' ? 'password' : 'text'}
            className={`absolute left-[${x}px] top-[${y}px] w-[${Math.min(room, Math.round(t.px * 30))}px] h-[${fh}px] px-[${Math.round(t.px * 0.5)}px] rounded-[${Math.round(t.px * 0.3)}px] text-[${t.px}px] ${box}`}
            value={f.value} placeholder={f.label}
            onChange={(e: any) => {
              f.value = String(e.target.value)
              rev++
            }}
            onKeyDown={(e: any) => {
              if (e.key === 'Enter') submit(f.form, -1)
            }} />
        )
      }
      continue
    }
    // A line of text.
    const size = Math.round(t.px * scaleOf(kind, meta))
    let cls = `absolute top-[${y}px] h-[${h}px] text-[${size}px] leading-[${h}px] whitespace-nowrap`
    if (kind === H) cls += ' font-bold'
    else if (kind === PRE) cls += t.ink ? '' : ' text-[#3c4043]'
    let barred = ''
    if (quote) barred = ` border-l-[${Math.max(2, Math.round(t.px * 0.2))}px] ${t.ink ? 'border-[#000000]' : 'border-[#c4c7c5]'} pl-[${Math.round(t.px * 0.6)}px]`
    const ps = pieces(d, b, r.from[i], r.to[i])
    let mark: any = null
    if (kind === LI && r.from[i] === 0) {
      const mw = Math.round(t.px * 1.3)
      mark = <div className={`absolute left-[${x - mw}px] top-[${y}px] w-[${mw - Math.round(t.px * 0.35)}px] h-[${h}px] text-[${size}px] leading-[${h}px] text-right whitespace-nowrap ${dim}`}>{d.mark[b]}</div>
    }
    if (mark) out.push(mark)
    if (quote) x -= Math.round(t.px * 0.6)
    let linked = false
    for (let k = 1; k < ps.length; k += 2) if (ps[k] >= LINK) linked = true
    if (ps.length === 2 && !ps[1]) {
      const s = kind === PRE ? ps[0].replace(/ /g, ' ') : ps[0]
      out.push(<div className={`${cls} left-[${x}px]${barred}`}>{s}</div>)
      continue
    }
    const kids: any[] = []
    let lead = ''
    for (let k = 0; k < ps.length; k += 2) {
      let s: string = lead + ps[k]
      lead = ''
      const st: number = ps[k + 1]
      if (linked && s.trim() === '' && k + 2 < ps.length) {
        lead = s // a space alone is no item of a row: it goes with what follows
        continue
      }
      const link = st >= LINK ? Math.floor(st / LINK) : 0
      let c = ''
      if (st & BOLD) c += ' font-bold'
      if (st & ITALIC) c += ' italic'
      if (st & (DIM | STRUCK) && !link) c += ' ' + dim
      if (st & CODE && !t.ink) c += ' text-[#a03060]'
      if (linked) {
        // Each piece is an item of the row, so a link's own words take its tap; a space at an item's edge is kept as one.
        if (s.charCodeAt(0) === 32) s = ' ' + s.slice(1)
        if (s.charCodeAt(s.length - 1) === 32) s = s.slice(0, -1) + ' '
        if (link) kids.push(<span className={`shrink-0 ${linkCls}${c}`} onClick={() => go(link)} onLongPress={() => hold(link)}>{s}</span>)
        else kids.push(<span className={`shrink-0${c}`}>{s}</span>)
      } else kids.push(c ? <span className={c}>{s}</span> : s)
    }
    out.push(<div className={`${cls} left-[${x}px]${linked ? ' flex' : ''}${barred}`}>{kids}</div>)
  }
  const height = r.y[last - 1] + r.h[last - 1] - top
  return <div className={`absolute left-0 top-[${top - props.gy}px] w-full h-[${height}px]`}>{out}</div>
})

const ICONS = {
  back: 'M20,11V13H8L13.5,18.5L12.08,19.92L4.16,12L12.08,4.08L13.5,5.5L8,11H20Z',
  forward: 'M4,11V13H16L10.5,18.5L11.92,19.92L19.84,12L11.92,4.08L10.5,5.5L16,11H4Z',
  reload:
    'M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z',
  stop: 'M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z',
  home: 'M10,20V14H14V20H19V12H22L12,3L2,12H5V20H10Z',
  menu: 'M3,6H21V8H3V6M3,11H21V13H3V11M3,16H21V18H3V16Z',
  up: 'M7.41,15.41L12,10.83L16.59,15.41L18,14L12,8L6,14L7.41,15.41Z',
  down: 'M7.41,8.58L12,13.17L16.59,8.58L18,10L12,16L6,10L7.41,8.58Z',
}

function bind(app: any) {
  if (appRef.app === app) return
  appRef.app = app
  page = null
  load = null
  failure = null
  typed = null
  held = ''
  menu = false
  scrollY = 0
  pages.clear()
  stage = null
  seq++
}

export function onEvent(app: any, context: any) {
  bind(app)
  if (context.event === 'back') {
    if (menu || held) {
      menu = false
      held = ''
      return true
    }
    return step(-1)
  }
  if (context.event === 'forward') return step(1)
  return false
}

// A round panel: the address in the arc at the top, the buttons in the arc at
// the bottom, and the page between them as wide as the circle lets it be.
export function get(app: any, context: any) {
  if (!context || context.round !== true) return draw(app, context)
  const W = context.imageWidth
  const H = context.imageHeight
  const R = Math.min(W, H) / 2 - 12
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const top = Math.round(H / 2 - R * 0.66)
  const bottom = Math.round(H / 2 + R * 0.58)
  return draw(app, { ...context, imageWidth: chord(R * 0.66), imageHeight: bottom - top, roundBrowser: { W, H, R, chord, top, bottom } })
}

function draw(app: any, context: any) {
  inGet = true
  try {
    return paint(app, context)
  } finally {
    inGet = false
  }
}

function paint(app: any, context: any) {
  bind(app)
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const embedded = app.frame.embedded === true
  const fast = app.frame.fast ?? !paper
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // The browser's own parts by the frame's size: twice as big on a 4K screen or large e-paper, smaller under 480.
  const shortSide = Math.min(app.frame.width, app.frame.height)
  const z = shortSide >= (paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : Math.max(0.75, shortSide / 480)
  const zoomAt = Math.max(0, Math.min(ZOOMS.length - 1, Number(kept('zoom', 3))))
  const px = Math.max(9, Math.round(17 * z * ZOOMS[zoomAt]))
  const pics = kept('pics', fast ? 1 : 0) === 1
  const bar = Math.round(40 * z)
  viewH = Math.max(80, height - bar)
  embeddedNow = embedded
  // A new home page in the scene's settings is opened.
  const home = homeOf(app)
  if (kept('home', '') !== home) {
    frameos.remember('home', home)
    if (kept('nav', null)) open(home)
  }

  const nav = readNav(app)
  const entry = nav.list[nav.at]
  const want = idOf(entry)
  if (stage && stage.id !== want) {
    // Gone elsewhere while a page was coming: it is let go.
    if (load) load.stop = true
    load = null
    stage = null
  }
  for (let tries = 0; tries < 4; tries++) {
    if ((page && page.id === want) || (stage && stage.id === want) || (failure && failure.url === want)) break
    const seen = pages.get(want)
    if (load) load.stop = true
    load = null
    stage = null
    if (seen) {
      page = seen
      pending = entry.b !== undefined ? entry : null
      if (!pending) jumpTo(0)
      const hash = entry.u.indexOf('#')
      if (!pending && hash > 0) jumpToId(entry.u.slice(hash + 1))
      break
    }
    begin(app, entry, embedded, fast)
    const p = stage as Page | null
    if (p && !p.loading && p.doc.refresh && hops < 3 && bare(p.doc.refresh) !== p.url) {
      // A page that sends the browser on (<meta http-equiv="refresh">): the page it names, in its place.
      hops++
      entry.u = p.doc.refresh
      saveNav(nav)
      stage = null
      continue
    }
    break
  }
  if (stage && stage.id === want && (!stage.loading || (fast && load && load.shown))) {
    // Enough of the page coming to show: it takes the screen.
    page = stage
    stage = null
    if (!pending) jumpTo(0)
  }
  if (page && !page.loading && page.id === want && page.doc.refresh && hops < 3 && bare(page.doc.refresh) !== page.url) {
    hops++
    entry.u = page.doc.refresh
    saveNav(nav)
    begin(app, entry, embedded, fast)
  }
  // The page before stays up while the next one comes; a failure takes its place.
  const failed = failure && failure.url === want ? failure : null
  const showing = failed ? null : page
  const busy = !!stage || (!!page && page.loading)

  const contentW = width
  const look: Look = { width: contentW, px, pics, tall: Math.round(viewH * 0.6), jpegs: embedded }
  theme = { ink, fast, px, z, width: contentW, look }
  let total = 0
  let slots: any[] = []
  if (showing && !showing.picture && !showing.other && showing.doc.n) {
    const key = `${contentW} ${px} ${pics ? 1 : 0}`
    if (!showing.rows || showing.key !== key) {
      // Another width or text size: set again, the same words at the top.
      if (showing.rows && !pending) {
        const was: Entry = { u: entry.u }
        mark(was)
        pending = was
      }
      showing.rows = rows(showing.doc, look)
      showing.key = key
      rev++
    }
    const r = showing.rows
    r.doc = showing.doc
    if (pending && pending.b !== undefined && showing.id === want) {
      // Back where it was: rows as far as that block, then its line at the top.
      const target = pending
      let guard = 0
      while (r.next <= (target.b as number) && r.next < showing.doc.n && guard++ < 10000) reach(r, r.bottom + viewH)
      const row = rowOf(r, target.b as number, target.o || 0)
      if (row >= 0) {
        jumpTo(r.y[row] - Math.round(px * 0.4))
        pending = null
      } else if (!showing.loading) pending = null
    }
    const over = Math.round(viewH * 0.3)
    reach(r, scrollY + viewH + over * 2)
    total = showing.loading ? Math.max(heightOf(r), scrollY + viewH) : heightOf(r)
    // The rows that show and a few around them, in pieces of CHUNK, each at its own place in a ring.
    const a = Math.max(0, rowAt(r, scrollY - over))
    const b = Math.min(r.n, rowAt(r, scrollY + viewH + over) + 1)
    const ca = Math.floor(a / CHUNK)
    const cb = Math.max(ca, Math.floor(Math.max(a, b - 1) / CHUNK))
    const groups = Math.ceil(r.n / (CHUNK * GROUP))
    slots = []
    for (let g = 0; g < groups; g++) {
      const c0 = g * GROUP
      if (c0 > cb || c0 + GROUP <= ca) {
        slots.push(<div />)
        continue
      }
      const gy = r.y[c0 * CHUNK]
      const kids: any[] = []
      for (let c = c0; c < c0 + GROUP && c <= cb; c++) {
        if (c < ca) kids.push(<div />)
        else kids.push(<Chunk c={c} n={Math.min(r.n, (c + 1) * CHUNK) - c * CHUNK} gy={gy} id={showing.at} k={key + (ink ? 'i' : 'c')} rev={rev} />)
      }
      slots.push(<div className={`absolute left-0 top-[${gy}px] w-full`}>{kids}</div>)
    }
    built = [a < r.n ? r.y[a] : 0, b > 0 ? r.y[b - 1] + r.h[b - 1] : 0]
    if (r.next >= showing.doc.n && !showing.loading) built[1] = Infinity
    if (a === 0) built[0] = -Infinity
  }

  const icon = Math.round(21 * z)
  const text = Math.round(15 * z)
  // The browser's own parts take the look of a desktop around it (`look`, docs/jsx-ui.md "Themes"). The page is the web's.
  const button = (path: string, onClick: () => void, enabled = true, lit = false) => (
    <div look={lit ? 'selected' : 'button'}
      className={`flex items-center justify-center w-[${bar - Math.round(2 * z)}px] h-[${bar - Math.round(2 * z)}px] shrink-0 ${
        ink ? (lit ? 'bg-[#000000] text-[#ffffff]' : '') : lit ? 'bg-[#d3e3fd] text-[#0b57d0]' : enabled ? 'active:bg-[#d4d6d9] hover:bg-[#e3e5e8]' : ''
      } rounded-[${Math.round(4 * z)}px] cursor-pointer`}
      onClick={enabled ? onClick : () => {}}>
      <svg viewBox="0 0 24 24" className={`w-[${icon}px] h-[${icon}px] ${enabled ? '' : 'opacity-40'}`}>
        <path d={path} fill="currentColor" />
      </svg>
    </div>
  )
  const address = typed ?? (entry.u === 'about:home' ? '' : showing && showing.id === want && showing.doc.url !== showing.url && /^https?:/.test(showing.doc.url) ? showing.doc.url : entry.u)
  const quiet = ink ? 'text-[#000000]' : 'text-[#5f6368]'
  const plainButton = ink ? 'border-2 border-[#000000] text-[#000000] bg-[#ffffff]' : 'border border-[#c4c7c5] text-[#1f1f1f] bg-[#ffffff] active:bg-[#e3e5e8]'
  const page_ = (by: number) => jumpTo(Math.max(0, Math.min(Math.max(0, total - viewH), scrollY + by * (viewH - lineOf(px) * 2))))

  const backButton = button(ICONS.back, () => step(-1), nav.at > 0)
  const forwardButton = button(ICONS.forward, () => step(1), nav.at < nav.list.length - 1)
  const reloadButton = button(busy ? ICONS.stop : ICONS.reload, () => {
    if (busy && load) {
      const L = load
      settle(L, 'Stopped')
      L.stop = true
    } else reload()
  })
  const menuButton = button(ICONS.menu, () => (menu = !menu), true, menu)
  const upButton = button(ICONS.up, () => page_(-1), scrollY > 0)
  const downButton = button(ICONS.down, () => page_(1), scrollY + viewH < total - 1)
  const addressField = (
    <input look="field"
      className={`flex-1 min-w-0 h-[${bar - Math.round(10 * z)}px] px-[${Math.round(8 * z)}px] rounded-[${Math.round(4 * z)}px] text-[${text}px] ${
        ink ? 'border border-[#000000] text-[#000000] bg-[#ffffff]' : 'border border-[#d3d6da] bg-[#ffffff] text-[#1f1f1f] focus:border-[#0b57d0]'
      }`}
      value={address} placeholder="Search or type an address"
      onChange={(e: any) => {
        typed = String(e.target.value)
      }}
      onKeyDown={(e: any) => {
        if (e.key === 'Enter') {
          const url = normalize(typed ?? address)
          if (url) open(url)
        } else if (e.key === 'Escape') typed = null
      }} />
  )
  const note = showing && showing.note && !showing.loading ? showing.note : ''
  const pageBox = (
    <div className="flex flex-col flex-1 min-h-0 overflow-y-auto" scrollTop={scrollAttr}
      onScroll={(e: any) => {
        scrollY = e.scrollTop
        // The rows drawn still cover the screen: nothing to make again.
        if (scrollY >= built[0] && scrollY + viewH <= built[1]) return false
      }}>
      {showing && showing.picture ? (
        <div className="flex flex-1 items-center justify-center bg-[#202020]">
          <img src={showing.picture} className={`w-[${contentW}px] h-[${viewH}px] object-contain`} />
        </div>
      ) : showing && !showing.other ? (
        <>
          {note ? (
            <div className={`flex flex-col shrink-0 gap-[${Math.round(6 * z)}px] p-[${Math.round(10 * z)}px] text-[${text}px] ${ink ? 'border-b-2 border-[#000000]' : 'bg-[#fff8e1] text-[#5f4b00]'}`}>
              <span>{note}</span>
              <div className={`flex gap-[${Math.round(8 * z)}px]`}>
                <div look="button" className={`px-[${Math.round(10 * z)}px] py-[${Math.round(4 * z)}px] rounded ${plainButton}`} onClick={() => open(ARCHIVE + showing!.url)}>Archived copy</div>
                <div look="button" className={`px-[${Math.round(10 * z)}px] py-[${Math.round(4 * z)}px] rounded ${plainButton}`} onClick={() => (held = showing!.url)}>QR code</div>
              </div>
            </div>
          ) : null}
          <div className={`relative w-full h-[${Math.max(1, Math.round(total))}px] shrink-0`}>{slots}</div>
        </>
      ) : (
        <div className={`flex flex-col items-center justify-center flex-1 gap-[${Math.round(10 * z)}px] p-[${Math.round(16 * z)}px] text-[${text}px]`}>
          {failed || (showing && showing.other) ? (
            <>
              <span className={`text-[${Math.round(text * 1.3)}px] font-bold text-center`}>{failed ? 'This page did not load' : 'This is ' + showing!.other}</span>
              <span look="muted" className={`text-center ${quiet}`}>{failed ? failed.why : 'A frame cannot show it. Its QR code opens it on a phone.'}</span>
              <span look="muted" className={`text-center ${quiet} line-clamp-2`}>{entry.u}</span>
              <div className={`flex gap-[${Math.round(8 * z)}px]`}>
                {failed ? <div look="button" className={`px-[${Math.round(14 * z)}px] py-[${Math.round(6 * z)}px] rounded ${plainButton}`} onClick={() => reload()}>Try again</div> : null}
                {failed ? <div look="button" className={`px-[${Math.round(14 * z)}px] py-[${Math.round(6 * z)}px] rounded ${plainButton}`} onClick={() => open(ARCHIVE + entry.u)}>Archived copy</div> : null}
                <div look="button" className={`px-[${Math.round(14 * z)}px] py-[${Math.round(6 * z)}px] rounded ${plainButton}`} onClick={() => (held = entry.u)}>QR code</div>
              </div>
            </>
          ) : (
            <span look="muted" className={quiet}>{'Opening ' + hostOf(entry.u) + '…'}</span>
          )}
        </div>
      )}
    </div>
  )
  const heldBox = held ? (
    <div className="absolute inset-0 flex items-center justify-center bg-black/50" onClick={() => (held = '')}>
      <div look="page"
        className={`flex flex-col gap-[${Math.round(8 * z)}px] w-[${Math.min(width - 32, Math.round(440 * z))}px] p-[${Math.round(14 * z)}px] rounded-[${Math.round(8 * z)}px] bg-[#ffffff] text-[#1f1f1f] text-[${text}px] ${ink ? 'border-2 border-[#000000]' : ''}`}
        onClick={() => {}}>
        <span look="muted" className={`text-[${Math.round(text * 0.85)}px] ${quiet} line-clamp-3`}>{held}</span>
        <div className="flex gap-[8px]">
          {/^https?:/.test(held) ? (
            <div look="primary" className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded ${ink ? 'bg-[#000000]' : 'bg-[#0b57d0]'} text-[#ffffff] font-bold cursor-pointer`}
              onClick={() => open(held)}>
              Open
            </div>
          ) : null}
          <a look="button" href={held} className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded ${plainButton} cursor-pointer`}>QR code</a>
          <div look="button" className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded ${plainButton} cursor-pointer`} onClick={() => (held = '')}>Cancel</div>
        </div>
      </div>
    </div>
  ) : null
  const item = (label: string, onClick: () => void, on = true) => (
    <div look="button" className={`flex items-center h-[${Math.round(38 * z)}px] px-[${Math.round(14 * z)}px] whitespace-nowrap ${on ? (ink ? '' : 'active:bg-[#e3e5e8]') : 'opacity-40'}`}
      onClick={on ? () => { menu = false; onClick() } : () => {}}>
      {label}
    </div>
  )
  const marked = !!showing && marks(app).some((m) => m[1] === showing!.url)
  const feedOf = showing && showing.doc.feeds.length ? resolve(showing.doc.feeds[0], showing.doc.base) : ''
  const menuBox = menu ? (
    <div className="absolute inset-0" onClick={() => (menu = false)}>
      <div look="page"
        className={`absolute right-[${Math.round(4 * z)}px] top-[${bar}px] flex flex-col py-[${Math.round(4 * z)}px] rounded-[${Math.round(6 * z)}px] bg-[#ffffff] text-[#1f1f1f] text-[${text}px] max-h-[${viewH - Math.round(8 * z)}px] overflow-y-auto ${ink ? 'border-2 border-[#000000]' : 'border border-[#c4c7c5]'}`}
        onClick={() => {}}>
        {item('Start page', () => open('about:home'))}
        {item(marked ? 'Remove bookmark' : 'Bookmark this page', () => toggleMark(app), !!showing && /^https?:/.test(showing.url))}
        {item('History', () => open('about:history'))}
        <div className={`flex items-center h-[${Math.round(38 * z)}px] px-[${Math.round(14 * z)}px] gap-[${Math.round(10 * z)}px]`}>
          <span className="flex-1">Text size</span>
          <div look="button" className={`flex items-center justify-center w-[${Math.round(34 * z)}px] h-[${Math.round(30 * z)}px] rounded ${plainButton}`}
            onClick={() => frameos.remember('zoom', Math.max(0, zoomAt - 1))}>
            {'−'}
          </div>
          <div look="button" className={`flex items-center justify-center w-[${Math.round(34 * z)}px] h-[${Math.round(30 * z)}px] rounded ${plainButton}`}
            onClick={() => frameos.remember('zoom', Math.min(ZOOMS.length - 1, zoomAt + 1))}>
            +
          </div>
        </div>
        {item(pics ? 'Pictures: on' : 'Pictures: off', () => frameos.remember('pics', pics ? 0 : 1))}
        {item('Top of the page', () => jumpTo(0), scrollY > 0)}
        {item('This site’s feed', () => open(feedOf), !!feedOf)}
        {item('Archived copy', () => open(ARCHIVE + showing!.url), !!showing && /^https?:/.test(showing.url))}
        {item('QR code of this page', () => (held = showing!.doc.url), !!showing && /^https?:/.test(showing.doc.url))}
      </div>
    </div>
  ) : null
  // How far the page has come, under the toolbar, while it downloads.
  const coming = stage || (page && page.loading ? page : null)
  const progress = coming && fast ? (
    <div className={`absolute left-0 top-[${bar - Math.round(3 * z)}px] h-[${Math.round(3 * z)}px] w-[${Math.round(Math.min(0.92, 0.12 + (coming.bytes / (coming.bytes + 150000)) * 0.9) * width)}px] bg-[#0b57d0]`} />
  ) : null

  const round = context && context.roundBrowser
  if (round) {
    const { W, H, R, chord, top, bottom } = round
    const cap = ink ? 'bg-[#ffffff] text-[#000000]' : 'bg-[#f1f3f4] text-[#3c4043]'
    const line = ink ? 'border-[#000000]' : 'border-[#d3d6da]'
    const addressTop = Math.round(H / 2 - R * 0.86)
    const addressW = chord(R * 0.86)
    const rowTop = bottom + Math.round(4 * z)
    const rowW = chord(rowTop + bar - H / 2)
    return (
      <div look="page" className={`relative w-[${W}px] h-[${H}px] bg-[#ffffff] text-[#1f1f1f]`}>
        <div look="bar" className={`absolute left-0 top-0 w-[${W}px] h-[${top}px] border-b ${line} ${cap}`} />
        <div look="bar" className={`absolute left-0 top-[${bottom}px] w-[${W}px] h-[${H - bottom}px] border-t ${line} ${cap}`} />
        <div className={`absolute left-[${Math.round((W - addressW) / 2)}px] top-[${addressTop}px] w-[${addressW}px] h-[${bar}px] flex items-center`}>{addressField}</div>
        <div className={`absolute left-[${Math.round((W - width) / 2)}px] top-[${top}px] w-[${width}px] h-[${bottom - top}px] flex flex-col`}>{pageBox}</div>
        <div className={`absolute left-[${Math.round((W - rowW) / 2)}px] top-[${rowTop}px] w-[${rowW}px] h-[${bar}px] flex items-center justify-center gap-[${Math.round(2 * z)}px] ${cap}`}>
          {backButton}
          {forwardButton}
          {reloadButton}
          {menuButton}
        </div>
        {menuBox}
        {heldBox}
      </div>
    )
  }
  return (
    <div look="page" className="relative flex flex-col w-full h-full bg-[#ffffff] text-[#1f1f1f]">
      <div look="bar"
        className={`flex items-center h-[${bar}px] shrink-0 gap-[${Math.round(1 * z)}px] px-[${Math.round(2 * z)}px] ${
          ink ? 'bg-[#ffffff] border-b border-[#000000] text-[#000000]' : 'bg-[#f1f3f4] border-b border-[#d3d6da] text-[#3c4043]'
        }`}>
        {backButton}
        {width >= 420 ? forwardButton : null}
        {reloadButton}
        {addressField}
        {!fast ? upButton : null}
        {!fast ? downButton : null}
        {menuButton}
      </div>
      {pageBox}
      {progress}
      {menuBox}
      {heldBox}
    </div>
  )
}

sources.page.ts:
// What a page is once it is read: a Doc, a flat list of blocks (a paragraph, a
// heading, a list item, a line of a table, preformatted text, a picture, a
// form's field) with the text of each, where its links, bold and code runs
// start, and the parts of it folded away (its navigation, footer, sidebars).
//
// HTML is read by the frame's runtime as it downloads (fetch's `digest:
// "html"`, docs/html-digest.md): scripts, style sheets, comments and what is
// hidden never reach JavaScript, and what does is a record a block, which
// take() turns into the Doc. What is around a page rather than of it (its
// navigation, a sidebar, the footer) comes marked, and is folded here if it
// is big enough to be worth a line. Feeds, plain text, Markdown and JSON are
// read here.

export const P = 0 // a paragraph
export const H = 1 // a heading (its level in `meta`)
export const LI = 2 // a list item (its mark in `mark`)
export const PRE = 3 // preformatted lines
export const HR = 4 // a rule
export const IMG = 5 // a picture (doc.imgs)
export const FIELD = 6 // a form's field (doc.fields)
export const FOLD = 7 // a part folded away (doc.folds)
export const ROW = 8 // a line of a table, or of a list of terms: set close to the one above
export const NONE = 9 // nothing (a fold that was not made)

// A run's style: these bits, and from LINK up the number of its link (doc.links, from 1).
export const BOLD = 1
export const ITALIC = 2
export const CODE = 4
export const DIM = 8
export const STRUCK = 16
export const LINK = 256

// A block's meta: its indent (lists), its quote depth, a gap above it, and
// from 8 bits up its heading level or the index of its picture, field or fold.
export const INDENT = 15
export const QUOTE = 16 // times the depth, up to 7
export const GAP = 128
export const SHIFT = 8

export type Img = { src: string; alt: string; w: number; h: number; link: number }
export type Field = {
  form: number
  type: string // text, password, checkbox, radio, select, submit, hidden, textarea
  name: string
  value: string
  label: string
  on?: boolean // a checkbox or radio that is ticked
  options?: string[] // a select's: value, text, value, text...
}
export type Form = { action: string; post: boolean; fields: number[] }
export type Fold = { at: number; end: number; open: boolean; label: string; links: number }
export type Doc = {
  url: string
  base: string // what its links are read against (<base href>)
  title: string
  n: number // how many blocks
  kind: number[]
  text: string[]
  // [where, style, where, style, ...]; null: one plain run. As it came ("0,257,11,0") until it is asked for:
  // most of a long page is never looked at, and a number read is a number paid for on an ESP32 (runsOf).
  runs: (number[] | string | null)[]
  meta: number[]
  mark: string[] // a list item's mark ("•", "3.")
  links: string[] // as the page wrote them; resolve() reads one against `base`
  imgs: Img[]
  fields: Field[]
  forms: Form[]
  folds: Fold[]
  // An id or a named anchor, and the block it is at: kept as they come (a long article has thousands, and
  // a page is asked for one or two of them), and looked up with idAt().
  idNames: string[]
  idBlocks: number[]
  feeds: string[] // the feeds the page names: url, title, url, title...
  refresh: string // <meta http-equiv="refresh">: where it sends the browser
  desc: string
  chars: number // of text kept
  cut: boolean // more came than is kept
  kindOf: string // html, text, feed, json
  max: number // text kept at most
  main: boolean // its own part was found
  ld: string // its JSON-LD, for a page that shows nothing without scripts
  wire: number[] // the runtime's number of each fold it marked, to its place in `folds`
}


export function blank(url: string, max = 2000000): Doc {
  const d: Doc = { url, base: url, title: '', n: 0, kind: [], text: [], runs: [], meta: [], mark: [], links: [''], imgs: [],
    fields: [], forms: [], folds: [], idNames: [], idBlocks: [], feeds: [], refresh: '', desc: '', chars: 0, cut: false, kindOf: 'html', max,
    main: false, ld: '', wire: [] }
  add(d, NONE, '', null, 0) // block 0: the fold of what comes before the page's own part
  return d
}

// The block an id names, or -1.
export function idAt(d: Doc, id: string): number {
  const at = d.idNames.indexOf(id)
  return at < 0 ? -1 : d.idBlocks[at]
}

// A block's runs, read from how they came the first time they are asked for.
export function runsOf(d: Doc, block: number): number[] | null {
  const runs = d.runs[block]
  if (typeof runs !== 'string') return runs
  return (d.runs[block] = JSON.parse('[' + runs + ']'))
}

export function add(d: Doc, kind: number, text: string, runs: number[] | string | null, meta: number): number {
  d.kind.push(kind)
  d.text.push(text)
  d.runs.push(runs)
  d.meta.push(meta)
  d.mark.push('')
  d.chars += text.length
  return d.n++
}

// --- the runtime's records of a page (docs/html-digest.md), into the Doc ---

const KINDS: Record<number, number> = { 112: P, 104: H, 108: LI, 114: PRE, 119: ROW } // p h l r w
const unline = (s: string) => (s.indexOf('\u000b') < 0 ? s : s.replace(/\u000b/g, '\n'))

// Records, whole ones, a line each. False once the Doc holds all it keeps.
export function take(d: Doc, records: string): boolean {
  let from = 0
  const n = records.length
  while (from < n) {
    let end = records.indexOf('\n', from)
    if (end < 0) end = n
    const c = records.charCodeAt(from)
    const kind = KINDS[c]
    if (kind !== undefined) {
      // A block of text: its place, where its runs start, its words.
      const a = records.indexOf('\t', from)
      const b = records.indexOf('\t', a + 1)
      const meta = parseInt(records.slice(from + 1, a), 10)
      const runs = b > a + 1 ? records.slice(a + 1, b) : null
      let text = unline(records.slice(b + 1, end))
      let mark = ''
      if (kind === LI) {
        const m = text.indexOf('\u0001')
        mark = text.slice(0, m)
        text = text.slice(m + 1)
      }
      const at = add(d, kind, text, runs, meta)
      if (mark) d.mark[at] = mark
    } else if (c === 65) d.links.push(records.slice(from + 1, end)) // A
    else if (c === 35) { // #
      d.idNames.push(records.slice(from + 1, end))
      d.idBlocks.push(d.n)
    } else other(d, c, records.slice(from + 1, end))
    from = end + 1
    if (d.chars > d.max) {
      d.cut = true
      return false
    }
  }
  return !d.cut
}

function other(d: Doc, c: number, rest: string) {
  const f = rest.split('\t')
  switch (c) {
    case 45: add(d, HR, '', null, parseInt(rest, 10) || 0); return // -
    case 105: // i: a picture
      d.imgs.push({ w: +f[1] || 0, h: +f[2] || 0, link: +f[3] || 0, src: f[4] || '', alt: f[5] || '' })
      add(d, IMG, f[5] || '', null, (parseInt(f[0], 10) || 0) + ((d.imgs.length - 1) << SHIFT))
      return
    case 70: d.forms.push({ post: f[0] === '1', action: f[1] || '', fields: [] }); return // F
    case 102: { // f: a field
      const field: Field = { form: +f[1], type: f[2], name: f[4] || '', value: unline(f[5] || ''), label: f[6] || '' }
      if (f[3] === '1') field.on = true
      if (field.type === 'select') field.options = f.slice(7)
      d.fields.push(field)
      const at = d.fields.length - 1
      if (field.form >= 0 && d.forms[field.form]) d.forms[field.form].fields.push(at)
      if (field.type !== 'hidden') add(d, FIELD, '', null, (parseInt(f[0], 10) || 0) + (at << SHIFT))
      return
    }
    case 91: { // [: something around the page starts; its line, if it is folded, goes here
      const at = add(d, NONE, '', null, parseInt(f[0], 10) || 0)
      d.wire.push(d.folds.length)
      d.folds.push({ at, end: -1, open: false, label: f[1] || '', links: d.links.length })
      return
    }
    case 83: if (d.folds[d.wire[+f[0]]]) d.folds[d.wire[+f[0]]].label = f[1] || ''; return // S: a <details>'s <summary>
    case 93: endFold(d, d.wire[+f[0]], +f[1], +f[2] || 0); return // ]
    case 77: foundMain(d); return // M
    case 84: d.title = rest; return // T
    case 66: d.base = resolve(rest, d.url) || d.base; return // B
    case 68: d.desc = rest; return // D
    case 82: d.refresh = resolve(rest, d.base); return // R
    case 69: if (d.feeds.length < 24) d.feeds.push(f[0], f[1] || 'Feed'); return // E
    case 74: d.ld = rest; return // J
    case 88: d.cut = true; return // X
  }
}

// Something around the page ended. flag 1: it is folded only if it is mostly links; 2: it starts open.
function endFold(d: Doc, f: number, flag: number, linkChars: number) {
  const fold = d.folds[f]
  if (!fold || fold.end >= 0) return
  fold.end = d.n
  let chars = 0
  let shown = 0
  for (let i = fold.at + 1; i < d.n; i++) {
    if (d.kind[i] === NONE) continue
    shown++
    chars += d.text[i].length
  }
  const links = d.links.length - fold.links
  fold.links = links
  // Too little to be worth a line of its own, or text rather than links: left as it is.
  if (shown < 2 || (shown < 3 && chars < 120) || (flag === 1 && (links < 3 || linkChars * 2 < chars))) {
    fold.end = fold.at
    return
  }
  if (!fold.label) fold.label = 'Details'
  fold.open = flag === 2
  d.kind[fold.at] = FOLD
  d.meta[fold.at] = (d.meta[fold.at] & 255) + (f << SHIFT)
}

// The page's own part starts: everything before it is folded into one line at its top.
function foundMain(d: Doc) {
  if (d.main) return
  d.main = true
  // What is open around it holds the page: it is no fold.
  for (const f of d.folds) if (f.end < 0 && f.label) f.end = f.at
  let shown = 0
  for (let i = 1; i < d.n; i++) if (d.kind[i] !== NONE) shown++
  if (shown < 2) return
  d.kind[0] = FOLD
  d.meta[0] = d.folds.length << SHIFT
  d.folds.push({ at: 0, end: d.n, open: false, label: 'Top of the page', links: d.links.length - 1 })
}

// The page ended: a page that showed nothing says what it can.
export function finish(d: Doc): Doc {
  for (const f of d.folds) if (f.end < 0) f.end = d.n
  let shown = 0
  for (let i = 0; i < d.n && shown < 400; i++) if (d.kind[i] !== NONE && d.kind[i] !== FOLD) shown += d.text[i].length
  if (shown < 200 && d.kindOf === 'html') {
    // A page its scripts write: what it says of itself.
    const said = fromLd(d.ld)
    if (said || d.desc) {
      if (d.title) add(d, H, d.title, null, 1 << SHIFT)
      for (const para of (said || d.desc).split(/\n+/)) if (para.trim()) add(d, P, para.trim(), null, GAP)
    }
  }
  d.ld = ''
  return d
}

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0' }
