  .replace(/([A-Za-z]+[0-9]*)([^A-Za-z0-9])/g, (_, name: string, c: string) => ((ENTITIES[name] = c === ' ' ? ' ' : c), ''))

const ENTITY = /&(#x[0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]*);?/g
export function decode(text: string): string {
  if (text.indexOf('&') < 0) return text
  return text.replace(ENTITY, (all, name: string) => {
    if (name.charCodeAt(0) === 35) {
      const code = name.charCodeAt(1) === 120 || name.charCodeAt(1) === 88 ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      if (!(code > 0) || code > 0x10ffff || (code >= 0xd800 && code < 0xe000)) return '\ufffd'
      return code < 32 && code !== 9 && code !== 10 ? ' ' : String.fromCodePoint(code)
    }
    const known = ENTITIES[name]
    return known === undefined ? all : known
  })
}

const SPACES = /[ \t\n\r\f]+/g
const UNSEEN = /[\u00ad\u200b-\u200f\u2028\u2029\u202a-\u202e\u2060-\u2064\ufeff]/g

// A URL against the page's, or '' for one this browser does not open.
export function resolve(href: string, base: string): string {
  let h = href.trim()
  if (!h) return base
  if (h.indexOf('\n') >= 0 || h.indexOf('\t') >= 0) h = h.replace(/[\t\n\r]/g, '')
  const scheme = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(h)
  if (scheme) {
    const s = scheme[1].toLowerCase()
    if (s === 'http' || s === 'https') return /^https?:\/\/[^/]/i.test(h) ? h.replace(/ /g, '%20') : ''
    return s === 'mailto' || s === 'tel' || s === 'about' ? h : ''
  }
  const b = /^(https?:)\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i.exec(base)
  if (!b) return ''
  h = h.replace(/ /g, '%20')
  if (h.startsWith('//')) return b[1] + h
  if (h.charCodeAt(0) === 47) return b[1] + '//' + b[2] + dots(h)
  if (h.charCodeAt(0) === 35) return b[1] + '//' + b[2] + (b[3] || '/') + (b[4] || '') + h
  if (h.charCodeAt(0) === 63) return b[1] + '//' + b[2] + (b[3] || '/') + h
  const dir = (b[3] || '/').replace(/[^/]*$/, '')
  return b[1] + '//' + b[2] + dots(dir + h)
}

function dots(path: string): string {
  if (path.indexOf('/.') < 0) return path
  const cut = path.search(/[?#]/)
  const tail = cut < 0 ? '' : path.slice(cut)
  const out: string[] = []
  const parts = (cut < 0 ? path : path.slice(0, cut)).split('/')
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]
    if (part === '..') {
      if (out.length > 1) out.pop()
      if (i === parts.length - 1) out.push('')
    } else if (part === '.') {
      if (i === parts.length - 1) out.push('')
    } else out.push(part)
  }
  return (out.join('/') || '/') + tail
}

// An article's text out of the page's JSON-LD.
function fromLd(text: string): string {
  if (!text) return ''
  const m = /"articleBody"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text) || /"description"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text)
  if (!m) return ''
  try {
    return decode(String(JSON.parse('"' + m[1] + '"'))).slice(0, 60000)
  } catch (e) {
    return ''
  }
}

// Markup to the words in it.
export function strip(html: string): string {
  let t = html
  if (t.indexOf('<') >= 0) t = t.replace(/<(script|style)[^>]*>[^]*?<\/\1\s*>/gi, ' ').replace(/<[^>]*>/g, ' ')
  return decode(t).replace(SPACES, ' ').trim()
}

// --- feeds (RSS, Atom): each entry a heading that is its link, its date and what it says ---

const inner = (xml: string, name: string): string => {
  const m = new RegExp('<' + name + '(?:\\s[^>]*)?>([^]*?)</' + name + '\\s*>', 'i').exec(xml)
  if (!m) return ''
  const t = m[1].trim()
  const c = /^<!\[CDATA\[([^]*?)\]\]>$/.exec(t)
  return c ? c[1] : decode(t)
}

export type Feed = { d: Doc; rest: string; head: boolean }
export const feed = (d: Doc): Feed => ((d.kindOf = 'feed'), { d, rest: '', head: false })

// A piece of a feed: every entry that is whole is read, the rest waits for the next piece.
export function feedPush(f: Feed, piece: string, last: boolean): boolean {
  const d = f.d
  let s = f.rest + piece
  for (;;) {
    const m = /<(item|entry)[\s>]/i.exec(s)
    if (!m) break
    if (!f.head) {
      f.head = true
      const top = s.slice(0, m.index)
      d.title = strip(inner(top, 'title')).slice(0, 200)
      const desc = strip(inner(top, 'description') || inner(top, 'subtitle')).slice(0, 400)
      if (desc) {
        d.text[0] = desc
        d.kind[0] = P
        d.runs[0] = [0, DIM]
      }
    }
    const close = '</' + m[1]
    const end = s.toLowerCase().indexOf(close.toLowerCase(), m.index)
    if (end < 0) {
      s = s.slice(m.index)
      break
    }
    const item = s.slice(m.index, end)
    s = s.slice(end + close.length)
    let link = inner(item, 'link').trim()
    if (!link) {
      const href = /<link\b[^>]*?\bhref\s*=\s*["']([^"']+)["'][^>]*>/i.exec(item)
      if (href && !/rel\s*=\s*["'](?!alternate)/i.test(href[0])) link = decode(href[1])
    }
    let style = 0
    if (link) {
      d.links.push(link)
      style = (d.links.length - 1) * LINK
    }
    add(d, H, strip(inner(item, 'title')) || link || 'Untitled', [0, style], GAP + (3 << SHIFT))
    const date = (inner(item, 'pubDate') || inner(item, 'updated') || inner(item, 'published') || inner(item, 'dc:date')).trim()
      .replace(/^(\w{3}, \d+ \w{3} \d{4}).*$/, '$1').replace(/^(\d{4}-\d\d-\d\d)T(\d\d:\d\d).*$/, '$1 $2')
    if (date) add(d, P, date, [0, DIM], 0)
    let body = inner(item, 'content:encoded') || inner(item, 'content')
    const short = inner(item, 'description') || inner(item, 'summary')
    if (short.length > body.length || !body) body = short
    body = strip(body).slice(0, 700)
    if (body) add(d, P, body, null, 0)
    if (d.chars > d.max) {
      d.cut = true
      return false
    }
  }
  f.rest = last ? '' : s.length > 400000 ? '' : s
  return true
}

// --- what a page is, from its first bytes ---

// html, feed, text, json, or what it is that this cannot show ('pdf', 'binary', 'image').
export function sniff(head: string, type: string, url: string): string {
  const t = type.toLowerCase()
  const path = url.replace(/[?#].*$/, '').toLowerCase()
  if (/^image\//.test(t) || /\.(png|jpe?g|gif|webp|bmp)$/.test(path)) return 'image'
  if (t.indexOf('pdf') >= 0 || head.startsWith('%PDF')) return 'pdf'
  const start = head.slice(0, 1024).trimStart()
  const lower = start.slice(0, 600).toLowerCase()
  if (/<(rss|feed|rdf:rdf)[\s>]/.test(lower)) return 'feed'
  if (t.indexOf('html') >= 0) return 'html'
  if (t.indexOf('json') >= 0) return 'json'
  if (t.indexOf('text/plain') >= 0) return /\.(md|markdown)$/.test(path) ? 'markdown' : 'text'
  if (/^(audio|video|font)\/|octet-stream|zip|gzip|tar|msword|officedocument/.test(t)) return 'binary'
  if (/[\x00-\x08\x0e-\x1f]/.test(start.slice(0, 400))) return 'binary'
  if (lower.startsWith('<!doctype html') || /<(html|head|body|title|div|p|table|h1|a|meta|script)[\s>]/.test(lower)) return 'html'
  if (t.indexOf('xml') >= 0 && /<(rss|feed|rdf:rdf|channel)[\s>]/.test(head.slice(0, 4096).toLowerCase())) return 'feed'
  if ((start.charCodeAt(0) === 123 || start.charCodeAt(0) === 91) && /^[\[{]\s*("|\{|\[|\d|\]|\}|t|f|n)/.test(start)) return 'json'
  if (/\.(md|markdown)$/.test(path)) return 'markdown'
  return 'text'
}

// --- text that is not markup ---

export type Plain = { d: Doc; rest: string; para: string; pre: string[]; md: boolean; fence: boolean }

export function plain(d: Doc, markdown: boolean): Plain {
  d.kindOf = markdown ? 'markdown' : 'text'
  return { d, rest: '', para: '', pre: [], md: markdown, fence: false }
}

// A piece of plain text: lines that read on are a paragraph, lines laid out by
// hand (indented, columns of spaces, drawn boxes) stay as they are.
export function plainPush(p: Plain, piece: string, last: boolean): boolean {
  const r = p.d
  const s = p.rest + piece.replace(/\r\n?/g, '\n').replace(/\x1b\[[0-9;]*[A-Za-z]/g, '')
  let i = 0
  for (;;) {
    const nl = s.indexOf('\n', i)
    if (nl < 0) break
    plainLine(p, s.slice(i, nl))
    i = nl + 1
    if (r.chars > r.max) {
      r.cut = true
      return false
    }
  }
  p.rest = s.slice(i)
  if (last) {
    if (p.rest) plainLine(p, p.rest)
    p.rest = ''
    plainLine(p, '')
  }
  return true
}

const LAID = /^\s{2,}\S|\S\s{3,}\S|^\s*[|+\-=_*#~.]{4,}\s*$|\t|^\s*[|+].*[|+]\s*$/

function plainLine(p: Plain, line: string) {
  const r = p.d
  const endPara = () => {
    if (p.para) {
      if (p.md) mdBlock(r, p.para)
      else add(r, P, p.para.replace(/\n+$/, ''), null, GAP)
      p.para = ''
    }
  }
  const endPre = () => {
    if (p.pre.length) {
      while (p.pre.length && !p.pre[p.pre.length - 1].trim()) p.pre.pop()
      if (p.pre.length) add(r, PRE, p.pre.join('\n'), null, GAP)
      p.pre = []
    }
  }
  if (p.md && /^\s*(```|~~~)/.test(line)) {
    endPara()
    if (p.fence) endPre()
    p.fence = !p.fence
    return
  }
  if (p.fence) {
    p.pre.push(line)
    return
  }
  if (!line.trim()) {
    endPara()
    if (p.pre.length) p.pre.push('')
    return
  }
  if (p.md) {
    // A heading, a rule, a list item or a quote is a block of its own.
    if (/^\s{0,3}(#{1,6}\s|[-*+]\s|\d+[.)]\s|>|[-*_]{3,}\s*$|\|)/.test(line)) {
      endPara()
      endPre()
      mdBlock(r, line)
      return
    }
    if (/^(\s{4,}|\t)/.test(line) && !p.para) {
      p.pre.push(line.replace(/^(\s{4}|\t)/, ''))
      return
    }
    endPre()
    p.para += (p.para ? ' ' : '') + line.trim()
    return
  }
  if (LAID.test(line) && !/^\s{2,8}\S.{40,}$/.test(line)) {
    endPara()
    p.pre.push(line.replace(/\t/g, '    '))
    return
  }
  if (p.pre.length && p.pre[p.pre.length - 1] !== '' && line.length < 40 && !p.para) {
    p.pre.push(line) // a short line among laid out ones is one of them
    return
  }
  endPre()
  const t = line.trim()
  // A short line ends its paragraph (an address, a verse, a heading).
  if (p.para && p.para.length - p.para.lastIndexOf('\n') - 1 < 46 && p.para.indexOf('\n') < 0 && p.para.length < 46) p.para += '\n' + t
  else p.para += (p.para ? (p.para.endsWith('\n') ? '' : ' ') : '') + t
  if (t.length < 46) p.para += '\n'
}

const MD_INLINE = /(\*\*|__)(?=\S)(.+?)\1|(`+)(.+?)\3|!?\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)|(\*|_)(?=\S)([^*_]+?)\7|<((?:https?:\/\/)[^>\s]+)>/g

// A block of Markdown: what it is by how it starts, and the links, bold and code in its line.
function mdBlock(r: Doc, text: string) {
  const d = r
  let kind = P
  let meta = GAP
  let markText = ''
  let m: RegExpExecArray | null
  let t = text
  if ((m = /^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$/.exec(t))) {
    kind = H
    meta = GAP + (m[1].length << SHIFT)
    t = m[2]
  } else if (/^\s{0,3}([-*_])(\s*\1){2,}\s*$/.test(t)) {
    add(r, HR, '', null, 0)
    return
  } else if ((m = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/.exec(t))) {
    kind = LI
    meta = Math.min(15, 1 + (m[1].length >> 1))
    markText = m[2].length > 1 ? m[2].replace(')', '.') : '\u2022'
    t = m[3].replace(/^\[( |x)\]\s/i, (_, x: string) => (x === ' ' ? '[ ] ' : '[x] '))
  } else if ((m = /^\s{0,3}((?:>\s?)+)(.*)$/.exec(t))) {
    meta = GAP + QUOTE * Math.min(7, m[1].replace(/\s/g, '').length)
    t = m[2]
  } else if (/^\s*\|/.test(t)) {
    if (/^\s*\|?[\s:|-]+\|?\s*$/.test(t)) return
    kind = ROW
    meta = 0
    t = t.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim()).join('  |  ')
  }
  let out = ''
  const runs: number[] = [0, kind === H ? 0 : 0]
  let at = 0
  MD_INLINE.lastIndex = 0
  while ((m = MD_INLINE.exec(t))) {
    out += t.slice(at, m.index)
    at = m.index + m[0].length
    let style = 0
    let body = ''
    if (m[2] !== undefined) { style = BOLD; body = m[2] }
    else if (m[4] !== undefined) { style = CODE; body = m[4] }
    else if (m[6] !== undefined) {
      if (m[0].charCodeAt(0) === 33 && !m[5]) continue
      d.links.push(m[6])
      style = (d.links.length - 1) * LINK
      body = m[5] || m[6]
    } else if (m[8] !== undefined) { style = ITALIC; body = m[8] }
    else if (m[9] !== undefined) {
      d.links.push(m[9])
      style = (d.links.length - 1) * LINK
      body = m[9]
    }
    runs.push(out.length, style)
    out += body
    runs.push(out.length, 0)
  }
  out += t.slice(at)
  if (!out.trim()) return
  const i = add(r, kind, out, runs.length > 2 ? runs : null, meta)
  if (markText) d.mark[i] = markText
}

// JSON, set out a value a line.
export function jsonDoc(r: Doc, text: string) {
  r.kindOf = 'json'
  let shown = text
  try {
    shown = JSON.stringify(JSON.parse(text), null, 2)
  } catch (e) {
    // as it came
  }
  add(r, PRE, shown.slice(0, r.max), null, 0)
}

