import { get, onEvent, normalize } from './app'
import { FIELD, FOLD, H, IMG, LI, LINK, NONE, P, PRE, ROW, SHIFT, blank, feed, feedPush, finish, idAt, jsonDoc, plain, plainPush, resolve, runsOf, sniff,
  take } from './page'
import { cut, heightOf, pictureBox, reach, rowAt, rowOf, rows, widthOf } from './lay'

// A page as the runtime hands it over (docs/html-digest.md): Hacker News's
// front page, its header row, a story's two lines, a search form.
const HN = [
  'THacker News',
  'Eindex.rss\tRSS',
  'Anews',
  'Anewest',
  'w0\t0,257,11,0,12,512\tHacker News new',
  'Ahttps://example.com/story',
  'Afrom?site=example.com',
  'w128\t0,0,3,768,23,0,25,1024,36,0\t1. A story about frames (example.com)',
  'Auser?id=marius',
  'Aitem?id=1',
  'w0\t0,0,13,1280,19,0,22,1536\t42 points by marius | 12 comments',
  'F0\t//hn.algolia.com/',
  'p128\t\tSearch:',
  'f0\t0\ttext\t0\tq\t\t',
].join('\n') + '\n'

const STORY = [
  'TA story',
  '[0\tNavigation',
  'A/', 'A/a', 'A/b', 'A/c',
  'l1\t0,256\t•\u0001Home',
  'l1\t0,512\t•\u0001About',
  'l1\t0,768\t•\u0001Blog',
  'l1\t0,1024\t•\u0001Contact',
  ']0\t0\t21',
  'M',
  '#top',
  'h384\t\tA story about frames',
  'A/next',
  'p128\t0,0,12,1280,18,0\tA page with a link and words after it.',
  'i128\t640\t360\t0\t/pictures/frame.jpg\tA frame on a wall',
  '#end',
  'p128\t\tThe end.',
].join('\n') + '\n'

// Every string in the tree, in order.
function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false || node === true) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  return node.props ? find(node.props.children, test) : null
}

// What the tree says, its spaces (the no-break ones at a link's edge too) as one.
const said = (tree: any) => texts(tree).join(' ').replace(/[\s ]+/g, ' ')
// The element that says `text` and takes a tap.
const tappable = (tree: any, text: string) =>
  find(tree, (n) => !!n.props && typeof n.props.onClick === 'function' && texts(n).join('').replace(/ /g, ' ').trim() === text)

type Served = { records?: string; text?: string; type?: string; status?: number; url?: string }
let asked: { url: string; init: any }[] = []
const realFetch = (globalThis as any).fetch

// Pages by address, each handed over as a runtime that streams hands a page over: in pieces, inside the call.
function serve(pages: Record<string, Served>, piece = 200) {
  asked = []
  const f: any = (url: string, init: any) => {
    asked.push({ url, init })
    const page = pages[url]
    // No answer at all: the promise rejects (here at once: a test has no later).
    if (!page) return { then: (_: any, no: any) => no(new TypeError('fetch failed: getaddrinfo ENOTFOUND')) }
    return new Promise((ok) => {
      const digest = page.records !== undefined && init.digest === 'html'
      const info: any = { status: page.status || 200, url: page.url || url, headers: { 'content-type': page.type || 'text/html' }, done: false,
        bytes: 0, digest: digest ? 'html' : '' }
      const body = page.records ?? page.text ?? ''
      let go = true
      for (let at = 0; at < body.length && go; ) {
        // Records come whole; text in any cut.
        let to = Math.min(body.length, at + piece)
        if (digest) {
          const nl = body.indexOf('\n', to - 1)
          to = nl < 0 ? body.length : nl + 1
        }
        go = init.onChunk(body.slice(at, to), info) !== false
        at = to
      }
      if (go) {
        info.done = true
        init.onChunk('', info)
      }
      ok({ status: info.status, ok: true, url: info.url })
    })
  }
  f.chunks = true
  ;(globalThis as any).fetch = f
}

afterEach(() => {
  ;(globalThis as any).fetch = realFetch
})

const PAGES: Record<string, Served> = {
  'https://news.ycombinator.com/': { records: HN },
  'https://example.com/story': { records: STORY },
}
const show = (app: any) => get(app, makeContext())
