    const d = blank('https://news.ycombinator.com/')
    expect(take(d, HN)).toBe(true)
    finish(d)
    expect(d.title).toBe('Hacker News')
    expect(d.feeds).toEqual(['index.rss', 'RSS'])
    expect(d.links.slice(1, 4)).toEqual(['news', 'newest', 'https://example.com/story'])
    expect(d.kind.slice(1)).toEqual([ROW, ROW, ROW, P, FIELD])
    expect(d.text[2]).toBe('1. A story about frames (example.com)')
    expect(runsOf(d, 2)).toEqual([0, 0, 3, 768, 23, 0, 25, 1024, 36, 0])
    expect(d.forms[0]).toEqual({ post: false, action: '//hn.algolia.com/', fields: [0] })
    expect(d.fields[0].name).toBe('q')
    expect(resolve(d.links[4], d.base)).toBe('https://news.ycombinator.com/from?site=example.com')
  })

  it('is the same page whatever pieces its records come in', () => {
    const whole = blank('https://example.com/story')
    take(whole, STORY)
